13	/// Convert an RGB hex color code number to a color type
14	pub fn rgb(hex: u32) -> Rgba {
15	    let [_, r, g, b] = hex.to_be_bytes().map(|b| (b as f32) / 255.0);
16	    Rgba { r, g, b, a: 1.0 }
17	}
