136	impl From<Rgba> for u32 {
137	    fn from(rgba: Rgba) -> Self {
138	        let r = (rgba.r * 255.0) as u32;
139	        let g = (rgba.g * 255.0) as u32;
140	        let b = (rgba.b * 255.0) as u32;
141	        let a = (rgba.a * 255.0) as u32;
142	        (r << 24) | (g << 16) | (b << 8) | a
143	    }
