194	impl From<Hsla> for Rgba {
195	    fn from(color: Hsla) -> Self {
196	        let h = color.h;
197	        let s = color.s;
198	        let l = color.l;
199	
200	        let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
201	        let x = c * (1.0 - ((h * 6.0) % 2.0 - 1.0).abs());
202	        let m = l - c / 2.0;
203	        let cm = c + m;
204	        let xm = x + m;
205	
206	        let (r, g, b) = match (h * 6.0).floor() as i32 {
207	            0 | 6 => (cm, xm, m),
208	            1 => (xm, cm, m),
209	            2 => (m, cm, xm),
210	            3 => (m, xm, cm),
211	            4 => (xm, m, cm),
212	            _ => (cm, m, xm),
213	        };
214	
215	        Rgba {
216	            r: r.clamp(0., 1.),
217	            g: g.clamp(0., 1.),
218	            b: b.clamp(0., 1.),
219	            a: color.a,
220	        }
221	    }
222	}
