677	impl From<Rgba> for Hsla {
678	    fn from(color: Rgba) -> Self {
679	        let r = color.r;
680	        let g = color.g;
681	        let b = color.b;
682	
683	        let max = r.max(g.max(b));
684	        let min = r.min(g.min(b));
685	        let delta = max - min;
686	
687	        let l = (max + min) / 2.0;
688	        let s = if l == 0.0 || l == 1.0 {
689	            0.0
690	        } else if l < 0.5 {
691	            delta / (2.0 * l)
692	        } else {
693	            delta / (2.0 - 2.0 * l)
694	        };
695	
696	        let h = if delta == 0.0 {
697	            0.0
698	        } else if max == r {
699	            ((g - b) / delta).rem_euclid(6.0) / 6.0
700	        } else if max == g {
701	            ((b - r) / delta + 2.0) / 6.0
702	        } else {
703	            ((r - g) / delta + 4.0) / 6.0
704	        };
705	
706	        Hsla {
707	            h,
708	            s,
709	            l,
710	            a: color.a,
711	        }
712	    }
713	}
